class StrongRef<T> {
  constructor(private value: T) {}
  deref() {
    return this.value
  }
}

function createCacheNode<T>(): CacheNode<T> {
  return {
    s: UNTERMINATED,
    v: undefined,
    o: null,
    p: null
  }
}

